style.css:
@-moz-document domain("roblox.com") {
/* Fondo con imagen verde y rosa pastel */
  html, body, .container-main, .rbx-body {
    background: url("https://i.imgur.com/1fG9L7L.png") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Hacer contenido semi-transparente para que se vea el fondo */
  .container-main, .rbx-body {
    background-color: rgba(255, 255, 255, 0.85) !important;
    border-radius: 10px !important;
  }

  /* Opcional: cambiar color de botones a tonos pastel */
  .btn-primary, .btn-secondary {
    background-color: #ffb6b9 !important;
    color: #4a4a4a !important;
    border: none !important;
  }
}
